<div class="stack"><div><h1>Verifica offerte</h1><p class="muted">Controllo link affiliati, codice valido e stato operativo.</p></div><div class="table-wrap"><table class="table"><thead><tr><th>Store</th><th>Offerta</th><th>Stato</th><th>Verificata</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?php echo e($item['store']); ?></td><td><?php echo e($item['offer']); ?></td><td><span class="tag <?php echo strtolower($item['status']) === 'expired' ? 'status-expired' : 'status-valid'; ?>"><?php echo e($item['status']); ?></span></td><td><?php echo e($item['checked_at']); ?></td></tr><?php endforeach; ?></tbody></table></div></div>
